using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckDodgeball {public sealed class DodgeProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsDodgeProbe")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.DodgeProbe",false);UnityEditor.SessionState.SetBool("LWS.DodgeProbe",false);
