 if(run){var g=new GameObject("Owned physical trampoline Dodgeball acceptance");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<DodgeProbe>();}}
 DodgeMatch m;string folder,key,saved;bool had,restored;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 void Awake(){folder=SportsEvidencePaths.Folder("DodgeEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;}
 IEnumerator Start(){Check(DodgeFixtures.Run()>20,"authoritative team, live-ball, same-step draw, lock, first-three and rematch fixtures");yield return SportsProbeScene.Ensure<DodgeMatch>("TruckTrampolineDodgeball");m=FindAnyObjectByType<DodgeMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);
 for(int test=0;test<3&&errors==0;test++){m.SetupScreen();m.option=0;m.teamA=m.teamB=test==0?1:test==1?4:2;m.NormalizeSetup();m.AllBots();for(int i=0;i<m.setup.count;i++)m.setup.players[i].difficulty=(BowlingDifficulty)test;Check(m.StartMatch(),"full physical Dodgeball match starts difficulty="+test+" teams="+m.teamA+"v"+m.teamB);Time.timeScale=7;float deadline=Time.realtimeSinceStartup+1200,next=0,peakY=0;bool pause=false,replay=false;while(!m.Finished&&Time.realtimeSinceStartup<deadline&&errors<10){for(int i=0;i<m.setup.count;i++)if(m.rules.alive[i])peakY=Mathf.Max(peakY,m.fighters[i].truck.body.position.y);replay|=m.Stage==DodgeStage.Replay&&m.replay.Playing;if(!pause&&m.Stage==DodgeStage.Playing&&m.Clock>1){m.Pause();var p=m.balls[0].body.position;var v=m.balls[0].body.linearVelocity;int round=m.rules.Round;yield return new WaitForSecondsRealtime(.15f);Check(p==m.balls[0].body.position&&v==m.balls[0].body.linearVelocity&&round==m.rules.Round,"pause preserves physical balls/velocity/team round");m.Resume();Time.timeScale=7;pause=true;}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE difficulty="+test+" round="+m.rules.Round+" stage="+m.Stage+" time="+m.Clock+" wins="+string.Join(",",m.rules.wins)+" bounces="+m.BounceCount+" strikes="+m.StrikeCount+" returns="+m.Returns+" eliminations="+m.Eliminations+" neutral="+m.Neutralizations+" contacts="+m.QueuedContacts+" draws="+m.Draws);next=Time.realtimeSinceStartup+2;}yield return null;}if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder+"/difficulty-"+test,slot=>m.rules.Winner<0?0:m.rules.Team(slot)==m.rules.Winner?1:2,slot=>(double?)m.rules.wins[m.rules.Team(slot)],slot=>m.rules.Team(slot)==m.rules.Winner);
 Check(m.Finished&&m.rules.Winner>=0&&m.rules.wins[m.rules.Winner]==3,"complete first-to-three actual Dodgeball match difficulty="+test);Check(m.BounceCount>0&&m.StrikeCount>0&&m.Eliminations>0&&peakY>1.5f&&replay,"actual trampoline contacts launch, finite strikes create live balls, physical enemy contacts eliminate and replay");Check(m.GroundContacts>0&&m.Neutralizations>0&&m.ContactPeak<64,"physical ground neutralization and bounded contact queue without discarded contacts");log.AppendLine("MATCH difficulty="+test+" winner="+m.rules.Winner+" rounds="+m.rules.Round+" wins="+string.Join(",",m.rules.wins)+" draws="+m.Draws+" bounces="+m.BounceCount+" strikes="+m.StrikeCount+" returns="+m.Returns+" eliminations="+m.Eliminations+" neutralizations="+m.Neutralizations+" friendly="+m.FriendlyContacts+" peakY="+peakY+" contactPeak="+m.ContactPeak);Time.timeScale=1;m.SetupScreen();}
 if(errors==0){m.teamA=m.teamB=4;m.NormalizeSetup();m.AllBots();Check(m.StartMatch()&&m.rules.Round==1&&m.rules.wins[0]==0&&m.rules.wins[1]==0&&m.Eliminations==0&&m.StrikeCount==0,"rematch resets every fighter/ball/score/contact state");m.SetupScreen();}Restore();log.AppendLine("ERRORS="+errors+". Rule fixtures labelled separately from actual NWH/PhysX trampoline, strike and ball-contact matches. No injected outcomes, human/hardware or rendered performance claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null&&m.menus!=null&&m.menus.pages!=null&&m.menus.pages.Length>0&&m.menus.pages[0]!=null)m.SetupScreen();if(key!=null){if(had)SportsPrefs.SetString(key,saved);else SportsPrefs.DeleteKey(key);SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
